/*
 * network_$phys_copy - Copy bytes between two physical addresses
 *
 * Original address: 0x00E0F120, 192 bytes (0x00E0F120 .. 0x00E0F1DF); the
 * first routine of the NETWORK code segment, before NETWORK_$INSTALL_NET,
 * with no map symbol (was FUN_00e0f120).
 * Generated by: Claude Opus 5.5
 *
 * Under ML lock 0x14 the source frame is mapped at the AST_$COPY_BUFF window
 * (0xFF8800) and the destination frame at the AST_$ZERO_BUFF window
 * (0xFF8C00), both with MMU flags 0x16; `len` bytes are copied from the
 * source's page offset to the destination's with OS_$DATA_COPY and both
 * frames are unmapped again.  Neither window is checked for overrun.
 *
 * Frame (link.w A6,-0x14; D2-D4 saved):
 *   (0x08,A6) dst_pa  longword (D0): byte address, frame = dst_pa >> 10
 *   (0x0C,A6) src_pa  longword (D1)
 *   (0x10,A6) len     word (D2), sign-extended for OS_$DATA_COPY
 * Callers: NETWORK_$READ_AHEAD (0x00E10034, 0x00E100CA, 0x00E10156) and
 * NETWORK_$PROCESS_PAGING_REQUEST (0x00E10F62).
 */

#include "network/network_internal.h"
#include "ast/ast.h"
#include "mmu/mmu.h"
#include "os/os.h"

/* MMU flags for the two windows: `pea (0x16).w` at 0x00E0F176 / 0x00E0F18A */
#define NETWORK_PHYS_COPY_MMU_FLAGS 0x16

void network_$phys_copy(uint32_t dst_pa, uint32_t src_pa, int16_t len)
{
    uint32_t src_ppn = src_pa >> 10;                                /* D3 */
    uint32_t dst_ppn = dst_pa >> 10;                                /* D4 */
    uint32_t src_va = ARCH_PTR_TO_VA(AST_$COPY_BUFF) + (src_pa & 0x3FF);  /* (-0xc,A6) */
    uint32_t dst_va = ARCH_PTR_TO_VA(AST_$ZERO_BUFF) + (dst_pa & 0x3FF);  /* (-0x8,A6) */

    ML_$LOCK(ML_LOCK_PMAP);                                         /* 0x00E0F16E */
    MMU_$INSTALL(src_ppn, src_va, 0, NETWORK_PHYS_COPY_MMU_FLAGS);
    MMU_$INSTALL(dst_ppn, dst_va, 0, NETWORK_PHYS_COPY_MMU_FLAGS);
    OS_$DATA_COPY(ARCH_VA_TO_PTR(src_va), ARCH_VA_TO_PTR(dst_va),
                  (uint32_t)(int32_t)len);                          /* 0x00E0F1AC */
    MMU_$REMOVE(src_ppn);
    MMU_$REMOVE(dst_ppn);
    ML_$UNLOCK(ML_LOCK_PMAP);
}
